[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path $full -PathType Leaf)){throw "Compile repair packet missing: $rel"};$raw=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $full)));if($raw -match '(?i)"(?:broadCleanup|suppressError|compatibilityShim)"\s*:\s*(?:true|"true")'){throw 'Compile repair packet declares a forbidden broad or suppressive fix.'};$p=$raw|ConvertFrom-Json;foreach($x in @('schemaVersion','errorId','layer','source','line','originalError','rootCause','patchScope','generatedProjectAllowed','verificationLayer','remainingErrors','untestedLayers','utf8')){if($null -eq $p.PSObject.Properties[$x]){throw "Compile repair field missing: $x"}};if([string]$p.schemaVersion -ne '1'-or [int]$p.line -lt 1){throw 'Compile repair schema or source line is invalid.'};if([bool]$p.generatedProjectAllowed){throw 'Generated project files must not be modified.'};if([string]$p.patchScope -notmatch '^(single-symbol|single-file-direct-cause)$'){throw 'Patch scope must remain single-error bounded.'};Write-Output "PASS: compile repair packet is single-error scoped, non-suppressive and verification-layer explicit: $rel"
